/* Datas em collectionsRecords são guardadas como deslocamento de dias a partir de BASE_DATE_ISO (fixo),
   para manter o dataset compacto e consistente mesmo após reimportar uma nova planilha. */
const BASE_DATE_ISO = "2026-05-01";
function baseDateObj() { const [y, m, d] = BASE_DATE_ISO.split("-").map(Number); return new Date(y, m - 1, d); }
function dayOffsetToISO(offset) { const d = new Date(baseDateObj()); d.setDate(d.getDate() + offset); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; }
function isoToDayOffset(iso) { const [y, m, d] = iso.split("-").map(Number); const target = new Date(y, m - 1, d); return Math.round((target - baseDateObj()) / 86400000); }
function formatDatePtBR(iso) { const [y, m, d] = iso.split("-"); return `${d}/${m}/${y}`; }
const WEEKDAYS_PT = ["Domingo", "Segunda-feira", "Terça-feira", "Quarta-feira", "Quinta-feira", "Sexta-feira", "Sábado"];
function weekdayLabel(iso) { const [y, m, d] = iso.split("-").map(Number); return WEEKDAYS_PT[new Date(y, m - 1, d).getDay()]; }

function parseImportedRules(rows) {
  if (!rows.length) throw new Error("A primeira aba não possui linhas de dados.");
  const headers = Object.keys(rows[0]).map(normalizeHeader);
  const find = (...names) => names.map(normalizeHeader).find((name) => headers.includes(name));
  const keys = {
    operation: find("tipo operação", "tipo operacao", "operacao"), vehicle: find("classe veículo", "veiculo", "tipo veiculo"), table: find("numero tabela", "tabela"), description: find("descrição tabela", "descricao tabela"), route: find("tipo de rota", "rota"), routeKm: find("km total rota", "km rota"), kmRate: find("valor km"), exemptKm: find("qt kms isento", "kms isentos", "franquia km"), minDailyQty: find("quantidade mínima de diária", "quantdidade mínima de diária", "quantidade minima de diaria"), maxDailyQty: find("quantidade máxima de diária", "quantidade maxima de diaria"), minDaily: find("valor diária mínima", "diaria minima"), maxDaily: find("valor diária máxima", "diaria maxima", "diaria"), excessDaily: find("qt diárias saída excedente", "diarias excedentes"), resource: find("valor recurso"), idrValue: find("valor idr"), idrPercent: find("percentual idr"), tde: find("vl tde"), overnight: find("vl pernoite"), mobile: find("vl mobile entregas"), hoursAbove: find("quantidade de horas acima"), note: find("observação", "observacao"),
  };
  const required = ["vehicle", "table", "kmRate", "exemptKm"].filter((key) => !keys[key]);
  if (!keys.minDaily && !keys.maxDaily) required.push("diária mínima ou máxima");
  if (required.length) throw new Error(`Cabeçalhos ausentes: ${required.join(", ")}.`);
  const sourceKey = (row, normalized) => normalized ? Object.entries(row).find(([key]) => normalizeHeader(key) === normalized)?.[1] : undefined;
  return rows.map((row) => {
    const vehicle = String(sourceKey(row, keys.vehicle) ?? "").trim();
    const minDaily = numeric(sourceKey(row, keys.minDaily));
    const sourceMaxDaily = numeric(sourceKey(row, keys.maxDaily)) || minDaily;
    const maxDaily = vehicle === "CAV.MECANICO" ? 696.52 : sourceMaxDaily;
    const kmRate = Number(numeric(sourceKey(row, keys.kmRate)).toFixed(2));
    return { operation: String(sourceKey(row, keys.operation) ?? "Entrega/Coleta").trim(), vehicle, table: numeric(sourceKey(row, keys.table)), description: String(sourceKey(row, keys.description) ?? "").trim(), route: String(sourceKey(row, keys.route) ?? "").trim(), routeKm: numeric(sourceKey(row, keys.routeKm)), kmRate, exemptKm: numeric(sourceKey(row, keys.exemptKm)), minDailyQty: numeric(sourceKey(row, keys.minDailyQty)), maxDailyQty: numeric(sourceKey(row, keys.maxDailyQty)), minDaily: vehicle === "CAV.MECANICO" ? 696.52 : (minDaily || maxDaily), maxDaily, excessDaily: numeric(sourceKey(row, keys.excessDaily)), hoursAbove: String(sourceKey(row, keys.hoursAbove) ?? ""), idrPercent: numeric(sourceKey(row, keys.idrPercent)), idrValue: numeric(sourceKey(row, keys.idrValue)), resource: numeric(sourceKey(row, keys.resource)), tde: numeric(sourceKey(row, keys.tde)), overnight: numeric(sourceKey(row, keys.overnight)), mobile: numeric(sourceKey(row, keys.mobile)), note: String(sourceKey(row, keys.note) ?? "").trim() || undefined };
  }).filter((rule) => rule.vehicle && rule.table && !excludedVehiclePattern.test(rule.vehicle));
}

function headerClient(value) { return String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim(); }

/* Data no formato "DD/MM/AAAA" ou "DD/MM/AAAA HH:MM:SS" (como vem em DT_EFETUAR_COLETAS) → "AAAA-MM-DD" */
function parseCollectionDate(value) {
  const text = String(value ?? "").trim();
  const match = text.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
  if (!match) return null;
  const [, day, month, year] = match;
  return `${year}-${month}-${day}`;
}

/* Relatório real de coletas (planilha "MyTable" exportada do sistema): usa DT_EFETUAR_COLETAS como data de
   referência, exclui coletas com DT_CANCELAMENTO preenchida, e agrupa por CNPJ_CLIENTES_SOL + Classe do
   Veículo + dia + status (uma linha por combinação, com a quantidade somada quando há repetição no mesmo dia). */
function parseCollectionsReport(rows) {
  if (!rows.length) throw new Error("A planilha não possui linhas de dados.");
  const headers = Object.keys(rows[0]).map(headerClient);
  const find = (...names) => names.map(headerClient).find((name) => headers.includes(name));
  const keys = {
    cnpj: find("cnpj clientes sol", "cnpj clientes"),
    name: find("razao social sol", "nm fantasia clientes"),
    vehicle: find("classe do veiculo", "classe veiculo"),
    date: find("dt efetuar coletas"),
    status: find("ds status coletas"),
    cancel: find("dt cancelamento"),
    nr: find("nr coletas"),
  };
  if (!keys.cnpj || !keys.name || !keys.vehicle || !keys.date) throw new Error("Não encontrei as colunas CNPJ_CLIENTES_SOL, RAZAO_SOCIAL_SOL, Classe do Veículo ou DT_EFETUAR_COLETAS na planilha.");
  const grouped = new Map();
  const names = new Map();
  let minDate = null, maxDate = null;
  const statusSet = new Set();
  for (const row of rows) {
    const entries = Object.entries(row);
    const value = (normalized) => normalized ? String(entries.find(([key]) => headerClient(key) === normalized)?.[1] ?? "").trim() : "";
    if (keys.cancel && value(keys.cancel)) continue;
    const cnpj = value(keys.cnpj);
    const name = value(keys.name);
    let vehicle = value(keys.vehicle).toUpperCase();
    const date = parseCollectionDate(value(keys.date));
    const status = keys.status ? value(keys.status).toUpperCase() || "EFETUADA" : "EFETUADA";
    const nr = keys.nr ? numeric(value(keys.nr)) : 0;
    if (!cnpj || !name || !date) continue;
    if (!["CAV.MECANICO", "TRUCK", "TOCO", "TOCO 3/4", "VAN", "FIORINO"].includes(vehicle)) vehicle = "OUTROS";
    names.set(cnpj, name);
    statusSet.add(status);
    if (!minDate || date < minDate) minDate = date;
    if (!maxDate || date > maxDate) maxDate = date;
    const key = `${cnpj}|${vehicle}|${date}|${status}`;
    const current = grouped.get(key);
    if (current) { current.count += 1; if (nr) current.nr.push(nr); }
    else grouped.set(key, { count: 1, nr: nr ? [nr] : [] });
  }
  if (!grouped.size) throw new Error("Nenhuma coleta com CNPJ, cliente e DT_EFETUAR_COLETAS válidos foi encontrada.");
  const cnpjs = Array.from(names.keys()).sort();
  const cnpjIndex = new Map(cnpjs.map((c, i) => [c, i]));
  const vehicleList = ["CAV.MECANICO", "TRUCK", "TOCO", "TOCO 3/4", "VAN", "FIORINO", "OUTROS"];
  const statusList = Array.from(statusSet.values());
  const base = baseDateObj();
  const records = Array.from(grouped.entries()).map(([key, value]) => {
    const [cnpj, vehicle, date, status] = key.split("|");
    const [y, m, d] = date.split("-").map(Number);
    const offset = Math.round((new Date(y, m - 1, d) - base) / 86400000);
    return [cnpjIndex.get(cnpj), vehicleList.indexOf(vehicle), offset, statusList.indexOf(status), value.count, value.nr.sort((a, b) => a - b)];
  });
  const validCollections = Array.from(grouped.values()).reduce((sum, v) => sum + v.count, 0);
  return { cnpjs, names: cnpjs.map((c) => names.get(c)), vehicleList, statusList, records, validCollections, rowCount: rows.length, periodStart: minDate, periodEnd: maxDate };
}

function normalizeName(value) { return String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim(); }

/* Relatório de coletas mensais: cada linha representa (por padrão) uma coleta/viagem realizada.
   Se a planilha já trouxer uma coluna de quantidade (ex.: "Qtd Coletas"), essa quantidade é somada
   em vez de contar 1 por linha. Linhas com o mesmo cliente são agrupadas e somadas. */
function parseMonthlyCollectionsReport(rows) {
  if (!rows.length) throw new Error("A planilha não possui linhas de dados.");
  const headers = Object.keys(rows[0]).map(headerClient);
  const find = (...names) => names.map(headerClient).find((name) => headers.includes(name));
  const nameKey = find("cliente", "nome cliente", "razao social", "razao social sol", "nm fantasia clientes", "nm fantasia", "cliente destino");
  const kmKey = find("km", "km total rota", "distancia km", "km rota");
  const qtyKey = find("quantidade coletas", "qtd coletas", "coletas", "qtd viagens", "quantidade viagens", "viagens", "quantidade", "qtd");
  if (!nameKey) throw new Error("Não encontrei uma coluna com o nome do cliente (ex.: 'Cliente' ou 'Razão Social').");
  const grouped = new Map();
  for (const row of rows) {
    const entries = Object.entries(row);
    const value = (normalized) => normalized ? entries.find(([key]) => headerClient(key) === normalized)?.[1] : undefined;
    const name = String(value(nameKey) ?? "").trim();
    if (!name) continue;
    const km = kmKey ? numeric(value(kmKey)) : undefined;
    const qty = qtyKey ? numeric(value(qtyKey)) || 1 : 1;
    const key = normalizeName(name);
    const current = grouped.get(key);
    grouped.set(key, { name: current?.name ?? name, trips: (current?.trips ?? 0) + qty, km: km || current?.km });
  }
  return Array.from(grouped.values()).sort((a, b) => b.trips - a.trips);
}

/* Persistência simples via window.storage (com fallback em memória caso indisponível) */
async function storageGet(key, fallback) {
  try {
    const result = await window.storage?.get(key, false);
    return result ? JSON.parse(result.value) : fallback;
  } catch {
    return fallback;
  }
}
async function storageSet(key, value) {
  try { await window.storage?.set(key, JSON.stringify(value), false); } catch { /* silencioso */ }
}

